#include <Arduino.h>
#include <DHT.h>
#include <math.h>

DHT sensor(7, DHT11);
unsigned long lastRead = 0;

void setup() {
  Serial.begin(9600);
  sensor.begin();
  lastRead = millis();
}

void loop() {
  unsigned long now = millis();
  if (now - lastRead >= 5000UL) {
    lastRead = now;
    float temperature = sensor.readTemperature();
    if (!isnan(temperature)) {
      Serial.print("Temperature: ");
      Serial.println(temperature, 1);
    }
  }
}
